#!/usr/bin/env bash
# toragents setup -- one line, then it prints two values to send back.
#
#   curl -fsSL <URL> | bash -s -- --peer-onion THEIR.onion --peer-fp THEIR_FP
#
# Installs: tor, a private tor instance with a persistent hidden service, a
# python venv, the inbox daemon, and background services. Idempotent: safe to
# re-run, never rotates an existing identity.
#
# Test without side effects:
#   TORAGENTS_FORCE_OS=mac bash setup.sh --dry-run --peer-onion x.onion --peer-fp 0123...
# Write the config but do not install/start the supervisors (containers, tests):
#   bash setup.sh --no-service --peer-onion x.onion --peer-fp 0123...
set -euo pipefail

# The daemon sources are embedded here as base64 by tools/embed.py. Fetching
# them from a ref was tried and removed: a force-moved tag served stale bytes
# from the CDN, so a pinned one-liner silently ran a mismatched installer.
PAYLOAD_INBOX=''
PAYLOAD_WIRE=''
PAYLOAD_PANEL=''
PAYLOAD_TRANSCRIPT=''
PAYLOAD_SIDECOL=''
PAYLOAD_POLICY=''
PAYLOAD_LEXICON=''
PAYLOAD_WATCH=''

HOME_DIR="${TORAGENTS_HOME:-$HOME/.toragents}"
PORT="${TORAGENTS_PORT:-8799}"
SOCKS="${TORAGENTS_SOCKS:-9061}"     # NOT 9050: that is a homebrew tor's default

PEER_ONION=""; PEER_FP=""; PEER_LABEL="peer"; DRY=0
NOSVC="${NOSVC:-0}"

while [ $# -gt 0 ]; do
  case "$1" in
    --peer-onion) PEER_ONION="$2"; shift 2 ;;
    --peer-fp)    PEER_FP="$2"; shift 2 ;;
    --peer-label) PEER_LABEL="$2"; shift 2 ;;
    --dry-run)    DRY=1; shift ;;
    --no-service) NOSVC=1; shift ;;
    --verify)     VERIFY_NAME="$2"; VERIFY_PATH="$3"; shift 3 ;;  # write units but never install/start them
    -h|--help) sed -n '2,12p' "$0"; exit 0 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

say() { printf '\n\033[1m%s\033[0m\n' "$*"; }
ok()  { printf '  \033[32mok\033[0m %s\n' "$*"; }
warn(){ printf '  \033[33mnote\033[0m %s\n' "$*"; }
die() { printf '\n\033[31mSTOP:\033[0m %s\n' "$*" >&2; exit 1; }

# ------------------------------------------------------------------ hashes ---
# Filled in by tools/pin_hashes.py from checksums published by the people who
# BUILT the artifacts -- never from a mirror, never from whatever we happened to
# download. No pinned hash for a file means we do not know the right answer for
# it, and the install stops rather than trusting the network.
SHA256_PINS="
cpython-3.11.17+20261013-aarch64-apple-darwin-install_only.tar.gz d81d757a9785850393cd695a9a686c765a6370fbdc83738589ef2ecd3e5c44b3
cpython-3.11.17+20261013-aarch64-pc-windows-msvc-install_only.tar.gz a1e65ec8fbfbb5dba01e3844ddc3e9ebcad446d6e6822cae9b1cc9717957dcef
cpython-3.11.17+20261013-x86_64-apple-darwin-install_only.tar.gz 3acde87324867dab4e63329be3010130c75bfc4a3709db00866862d750a3bba3
cpython-3.11.17+20261013-x86_64-pc-windows-msvc-install_only.tar.gz 7616ab1f74aab975bd91eb0a657a74a092a63a46cac38c5f3f9415c79fd781f5
cpython-3.11.17+20261013-x86_64-unknown-linux-gnu-install_only.tar.gz 846bf682e2b67393f2affa5e5c0994e446abc3a7cc5bb699890c36346823644c
tor-expert-bundle-linux-x86_64-15.0.25.tar.gz 19cf18726eecb362e0f21d27afa9ea9efe5da928bfdfbb1ceb5fe54519e87f4a
tor-expert-bundle-macos-aarch64-15.0.25.tar.gz a3febb6179152b0b4f56a0f5cc57bf5cc8ecef7db35e7c3e9d5a044c8158c26c
tor-expert-bundle-macos-x86_64-15.0.25.tar.gz e1ae4d4a734d28bb590839188511deb3cebc26fcbce9df66d01b2c452060fe95
tor-expert-bundle-windows-x86_64-15.0.25.tar.gz c1988c701de2f24f7d098d1d6d7f507b58f27740d097f29c246e0524d639b252
"
sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  elif command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | cut -d' ' -f1
  else openssl dgst -sha256 "$1" | awk '{print $NF}'; fi
}
pin_for() { printf '%s\n' "$SHA256_PINS" | awk -v n="$1" '$1==n {print $2}'; }
verify_artifact() {
  # name path -- fail closed. A wrong hash is corruption or an attack; in both
  # cases the correct action is to stop, not to install it and hope.
  local name="$1" path="$2" want got
  want="$(pin_for "$name")"
  got="$(sha256_of "$path")"
  if [ -z "$want" ]; then
    die "no pinned SHA256 for $name (computed $got) -- refusing to run bytes nobody has vouched for"
  fi
  if [ "$want" != "$got" ]; then
    die "SHA256 mismatch for $name: expected $want, got $got -- refusing to install"
  fi
  ok "verified $name (sha256 ${got%${got#????????????????}}...)"
}
download_to() {
  if [ "$DRY" = 1 ]; then warn "dry-run: would download $1"; return 0; fi
  curl -fsSL "$1" -o "$2"
}

# setup.sh --verify <artifact-name> <path> checks one file against the pins and
# exits. Useful on its own: verify a download without installing anything.
if [ -n "${VERIFY_NAME:-}" ]; then
  verify_artifact "$VERIFY_NAME" "$VERIFY_PATH"
  exit 0
fi

# A second install, a Tor Browser, or a homebrew tor can already hold these
# ports, and tor's failure to bind shows up only as "waiting for hostname"
# until the install gives up. Pick the next free port instead of dying.
port_free() { # port
  # Runs before $PY is chosen (platform detection comes later), so find one now.
  local probe
  probe="$(command -v python3 || command -v python || true)"
  [ -n "$probe" ] || return 0        # no python yet: assume free, let tor decide
  "$probe" - "$1" <<'PYFREE' 2>/dev/null
import socket, sys
s = socket.socket()
try:
    s.bind(("127.0.0.1", int(sys.argv[1])))
except OSError:
    sys.exit(1)
finally:
    s.close()
PYFREE
}
pick_port() { # start -> first free port at or after start
  local p="$1" tries=0
  while [ "$tries" -lt 20 ]; do
    port_free "$p" && { printf '%s' "$p"; return 0; }
    p=$((p + 1)); tries=$((tries + 1))
  done
  printf '%s' "$1"
}
if ! port_free "$SOCKS"; then
  new_socks="$(pick_port $((SOCKS + 10)))"
  warn "socks port $SOCKS is in use (another tor?) -- using $new_socks"
  SOCKS="$new_socks"
fi
if ! port_free "$PORT"; then
  new_port="$(pick_port $((PORT + 1)))"
  warn "listener port $PORT is in use -- using $new_port"
  PORT="$new_port"
fi

# ------------------------------------------------------------- platform ---
if [ -n "${TORAGENTS_FORCE_OS:-}" ]; then
  OS="$TORAGENTS_FORCE_OS"
else
  case "$(uname -s)" in
    Linux)  OS=linux ;;
    Darwin) OS=mac ;;
    *) die "This script supports macOS and Linux.

Windows: tor has no service model this script can drive. Use WSL2 (the Linux
path then works unchanged) or run tor and the daemon in two terminals." ;;
  esac
fi
ok "platform: $OS"

# The homebrew prefix differs on Apple Silicon vs Intel.
BREW=""
if [ "$OS" = mac ]; then
  for b in /opt/homebrew/bin/brew /usr/local/bin/brew; do
    [ -x "$b" ] && { BREW="$b"; break; }
  done
  [ -n "$BREW" ] || command -v brew >/dev/null 2>&1 && BREW="${BREW:-$(command -v brew)}"
fi

# launchd does NOT inherit the shell PATH, so resolve absolute binaries now.
find_tor() {
  command -v tor >/dev/null 2>&1 && { command -v tor; return 0; }
  for t in /opt/homebrew/bin/tor /usr/local/bin/tor /usr/bin/tor /usr/sbin/tor; do
    [ -x "$t" ] && { echo "$t"; return 0; }
  done
  return 1
}

# macOS ships a python3 STUB that only exists to trigger an Xcode CLT install,
# so `command -v python3` can succeed while actually running fails. Test it.
find_python() {
  local c v
  for c in "$@" ; do
    command -v "$c" >/dev/null 2>&1 || continue
    "$c" -c 'import sys' >/dev/null 2>&1 || continue
    v="$("$c" -c 'import sys;print("%d.%d"%sys.version_info[:2])' 2>/dev/null)" || continue
    [ -n "$v" ] || continue
    "$c" -c 'import sys;sys.exit(0 if sys.version_info>=(3,10) else 1)' 2>/dev/null || continue
    echo "$c"; return 0
  done
  return 1
}

# Portable CPython from python-build-standalone: no package manager, no admin,
# same artifact for every OS/arch. This is what makes python a non-requirement.
PBS_TAG="${TORAGENTS_PBS_TAG:-20261013}"
PBS_VER="${TORAGENTS_PBS_VER:-3.11.17}"

install_portable_python() {
  local trip
  case "$(uname -s)-$(uname -m)" in
    Darwin-arm64)   trip=aarch64-apple-darwin ;;
    Darwin-x86_64)  trip=x86_64-apple-darwin ;;
    Linux-x86_64)   trip=x86_64-unknown-linux-gnu ;;
    Linux-aarch64)  trip=aarch64-unknown-linux-gnu ;;
    Linux-arm64)    trip=aarch64-unknown-linux-gnu ;;
    *) return 1 ;;
  esac
  local url="https://github.com/astral-sh/python-build-standalone/releases/download/${PBS_TAG}/cpython-${PBS_VER}+${PBS_TAG}-${trip}-install_only.tar.gz"
  mkdir -p "$HOME_DIR/python"
  local name="cpython-${PBS_VER}+${PBS_TAG}-${trip}-install_only.tar.gz" tmp
  tmp="$(mktemp "${TMPDIR:-/tmp}/toragents-python.XXXXXX")"
  download_to "$url" "$tmp" || { rm -f "$tmp"; return 1; }
  if [ "$DRY" = 1 ]; then rm -f "$tmp"; return 0; fi
  verify_artifact "$name" "$tmp" || { rm -f "$tmp"; return 1; }
  tar xzf "$tmp" -C "$HOME_DIR/python" --strip-components=1 || { rm -f "$tmp"; return 1; }
  rm -f "$tmp"
  local c="$HOME_DIR/python/bin/python3"
  [ -x "$c" ] || return 1
  echo "$c"
}

PY="$(find_python python3 /opt/homebrew/bin/python3 /usr/local/bin/python3 || true)"
if [ -z "$PY" ]; then
  say "No system python3 (3.10+) found -- fetching a portable one"
  if [ "$DRY" = 1 ]; then
    warn "dry-run: would download portable cpython $PBS_VER"
    PY=/tmp/portable/python/bin/python3
  else
    PY="$(install_portable_python || true)"
    [ -n "$PY" ] || die "could not fetch portable python for $(uname -s)-$(uname -m).
  Install python3.10+ manually and re-run, or set TORAGENTS_PBS_TAG/VER."
  fi
fi
ok "python: $PY ($("$PY" -c 'import sys;print("%d.%d.%d"%sys.version_info[:3])'))"

# ------------------------------------------------------------------ tor ---
# No Homebrew? tor publishes a self-contained macOS binary ("expert bundle"),
# so a Mac without brew can still run this. Nothing to compile.
TOR_BUNDLE_VER="${TORAGENTS_TOR_BUNDLE:-15.0.25}"
install_tor_expert_bundle() {
  local plat arch url
  # torproject publishes: macos aarch64/x86_64, linux x86_64, windows x86_64.
  # Linux arm64 has no bundle -- it falls back to the package manager.
  case "$(uname -s)" in
    Darwin) plat=macos ;;
    Linux)  plat=linux ;;
    *) return 1 ;;
  esac
  case "$(uname -m)" in
    arm64|aarch64) arch=aarch64 ;;
    x86_64|amd64)  arch=x86_64 ;;
    *) return 1 ;;
  esac
  [ "$plat-$arch" = "linux-aarch64" ] && return 1
  url="https://dist.torproject.org/torbrowser/${TOR_BUNDLE_VER}/tor-expert-bundle-${plat}-${arch}-${TOR_BUNDLE_VER}.tar.gz"
  mkdir -p "$HOME_DIR/tor-bin"
  local name="tor-expert-bundle-${plat}-${arch}-${TOR_BUNDLE_VER}.tar.gz" tmp
  tmp="$(mktemp "${TMPDIR:-/tmp}/toragents-tor.XXXXXX")"
  download_to "$url" "$tmp" || { rm -f "$tmp"; return 1; }
  if [ "$DRY" = 1 ]; then rm -f "$tmp"; return 0; fi
  verify_artifact "$name" "$tmp" || { rm -f "$tmp"; return 1; }
  tar xzf "$tmp" -C "$HOME_DIR/tor-bin" || { rm -f "$tmp"; return 1; }
  rm -f "$tmp"
  local t
  t="$(find "$HOME_DIR/tor-bin" -type f -name tor 2>/dev/null | head -1)"
  [ -n "$t" ] || return 1
  chmod +x "$t"
  xattr -d com.apple.quarantine "$t" 2>/dev/null || true
  echo "$t"
}

TORBIN="$(find_tor || true)"
if [ -z "$TORBIN" ]; then
  say "Installing tor"
  if [ "$DRY" = 1 ]; then
    warn "dry-run: would install tor"
    TORBIN=/usr/local/bin/tor
  elif [ "$OS" = mac ]; then
    if [ -n "$BREW" ]; then
      "$BREW" install tor
      TORBIN="$(find_tor || true)"
    else
      warn "no Homebrew; using the official tor expert bundle instead"
      TORBIN="$(install_tor_expert_bundle || true)"
      [ -n "$TORBIN" ] || die "could not fetch the tor expert bundle.
  Either install Homebrew (https://brew.sh) and re-run, or download tor
  manually from https://dist.torproject.org/torbrowser/"
    fi
  else
    if command -v apt-get >/dev/null 2>&1; then
      sudo apt-get update -qq && sudo apt-get install -y tor
    elif command -v dnf >/dev/null 2>&1; then
      sudo dnf install -y tor
    else
      warn "no package manager; using the official tor expert bundle"
      TORBIN="$(install_tor_expert_bundle || true)"
      [ -n "$TORBIN" ] || die "no tor and no bundle available for $(uname -s)-$(uname -m).
  Install tor manually and re-run."
    fi
    TORBIN="$(find_tor || true)"
    [ -n "$TORBIN" ] || TORBIN="$HOME_DIR/tor-bin/tor/tor"
    [ -x "$TORBIN" ] || die "tor installed but not found"
  fi
fi
ok "tor: $TORBIN"

# --------------------------------------------------------------- layout ---
mkdir -p "$HOME_DIR"
# state/ is always created: state/config.json is written even in a dry run, and
# a missing parent made that write fail silently in the dry-run path.
mkdir -p "$HOME_DIR/state/inbox" "$HOME_DIR/state/archive"
if [ "$DRY" = 1 ]; then
  say "dry-run: writing files under $HOME_DIR, no services started"
else
  mkdir -p "$HOME_DIR/hs" "$HOME_DIR/tor-data"
  chmod 700 "$HOME_DIR/tor-data" "$HOME_DIR/hs"
fi

# No AvoidDiskWrites: we depend on tor writing the hostname file at startup.
cat > "$HOME_DIR/torrc" <<TORRC
# managed by toragents setup -- safe to re-run
SocksPort 127.0.0.1:$SOCKS
DataDirectory $HOME_DIR/tor-data
HiddenServiceDir $HOME_DIR/hs
HiddenServicePort 80 127.0.0.1:$PORT
Log notice file $HOME_DIR/tor.log
TORRC
ok "torrc written (hidden service -> 127.0.0.1:$PORT, socks $SOCKS)"

# The daemon learns its ports from its service unit; the CLI does not. Without
# this record a bare `send` fell back to SOCKS 9050 and failed with
# "Connection refused" even though tor was listening on 9061.
printf '{"local_port": %s, "socks_port": %s}\n' "$PORT" "$SOCKS" > "$HOME_DIR/state/config.json"
ok "state/config.json written (cli uses socks $SOCKS)"

# ------------------------------------------------------------- python env ---
VPY="$HOME_DIR/venv/bin/python"
if [ "$DRY" = 0 ]; then
  [ -x "$VPY" ] || { say "Creating python environment"; "$PY" -m venv "$HOME_DIR/venv"; }
  "$VPY" -m pip install -q --upgrade pip
  if ! "$VPY" -c 'import nacl, socks' >/dev/null 2>&1; then
    say "Installing dependencies (PyNaCl, PySocks)"
    "$VPY" -m pip install -q PyNaCl PySocks
  fi
  "$VPY" -c 'import nacl, socks' || die "dependency install failed"
fi
ok "venv: $VPY"

# Self-contained: decode the embedded sources. No network, no ref lookup.
SRC_DIR=""
if [ -n "${BASH_SOURCE[0]:-}" ] && [ -f "${BASH_SOURCE[0]}" ]; then
  SRC_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
fi

decode() { # b64-string, dest
  printf '%s' "$1" | "$PY" -c 'import sys,base64;sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' > "$2"
}

if [ -n "$PAYLOAD_INBOX" ] && [ -n "$PAYLOAD_WIRE" ]; then
  decode "$PAYLOAD_INBOX" "$HOME_DIR/inbox_agent.py"
  [ -n "$PAYLOAD_LEXICON" ] && decode "$PAYLOAD_LEXICON" "$HOME_DIR/lexicon.seed.json"
  decode "$PAYLOAD_WIRE"  "$HOME_DIR/wire.py"
  ok "daemon installed (embedded)"
elif [ -n "$SRC_DIR" ] && [ -f "$SRC_DIR/inbox_agent.py" ]; then
  cp "$SRC_DIR/inbox_agent.py" "$SRC_DIR/wire.py" "$HOME_DIR/"
  ok "daemon installed (local source tree)"
else
  die "no embedded payload and no local sources. Run: python3 tools/embed.py"
fi

# ----------------------------------------------------------- auto-delivery ---
# A message sitting in a file is a mailbox: somebody has to go and look. The pi
# extension closes that gap -- it polls the inbox and pushes new messages into
# the live session as user turns, so nobody types "check your inbox".
#
# This is the ONLY delivery path by design. Claude Code and Codex have no
# equivalent that survives contact with reality: their hooks fire only on turns
# the human starts, fail silently when they fail, and cost a debugging round per
# harness. pi owns its own process, so pi gets a real push.
PI_EXT_DIR="$HOME/.pi/agent/extensions"
if [ -n "${PAYLOAD_WATCH:-}" ] && { [ -d "$HOME/.pi" ] || command -v pi >/dev/null 2>&1; }; then
  mkdir -p "$PI_EXT_DIR"
  decode "$PAYLOAD_WATCH" "$PI_EXT_DIR/toragents-inbox.ts"
  ok "pi extension installed -> messages arrive on their own"
elif [ -n "$SRC_DIR" ] && [ -f "$SRC_DIR/toragents_watch.ts" ]; then
  mkdir -p "$PI_EXT_DIR"
  cp "$SRC_DIR/toragents_watch.ts" "$PI_EXT_DIR/toragents-inbox.ts"
  ok "pi extension installed from source tree"
else
  die "pi not found (~/.pi missing). toragents is a pi extension: without it\n  nothing delivers the mail. Install pi first, then re-run this."
fi

# ---------------------------------------------------------------- reader ---
# The extension above DELIVERS mail; it does not show a conversation. The reader
# is a separate pi extension that renders what was said: a wide right-hand column
# for the session named as receiver, and a four-line strip at the bottom for every
# other chat. Installing it is optional in the sense that mail arrives without it,
# but "arrives" and "readable" are different promises, so it ships here by default.
#
# Files land with the names they import each other by: toragents-panel.ts imports
# ./_lib/toragents-*.ts, so the installer must not rename anything.
if [ -n "${PAYLOAD_PANEL:-}" ] && { [ -d "$HOME/.pi" ] || command -v pi >/dev/null 2>&1; }; then
  mkdir -p "$PI_EXT_DIR/_lib"
  decode "$PAYLOAD_PANEL"      "$PI_EXT_DIR/toragents-panel.ts"
  decode "$PAYLOAD_TRANSCRIPT" "$PI_EXT_DIR/_lib/toragents-transcript.ts"
  decode "$PAYLOAD_SIDECOL"    "$PI_EXT_DIR/_lib/toragents-side-column.ts"
  decode "$PAYLOAD_POLICY"     "$PI_EXT_DIR/_lib/toragents-policy.ts"
  ok "reader installed -> the conversation has a pane (strip by default)"
elif [ -n "$SRC_DIR" ] && [ -f "$SRC_DIR/toragents-panel.ts" ]; then
  mkdir -p "$PI_EXT_DIR/_lib"
  cp "$SRC_DIR/toragents-panel.ts" "$PI_EXT_DIR/"
  cp "$SRC_DIR"/_lib/toragents-*.ts "$PI_EXT_DIR/_lib/"
  ok "reader installed from source tree"
fi

# Placement policy. Absent, the old behaviour holds (first session to claim
# delivery gets untargeted mail, and every chat gets the strip); present, the
# named session is the front desk and gets the wide column. Written once, never
# overwritten -- a receiver name is a human decision, not an installer default.
POLICY="$HOME_DIR/policy.json"
if [ ! -f "$POLICY" ]; then
  printf '%s\n' '{' \
    '  "receiver": "",' \
    '  "panel": { "default": "strip", "column": [] },' \
    '  "fallbackToAnyone": true' \
    '}' > "$POLICY"
  say "wrote $POLICY -- set \"receiver\" to the session name that should get the wide column"
fi

# -------------------------------------------------------------- services ---
say "Installing background services"

# The flusher loop lives in a script rather than inline in the unit for one
# boring reason: an inline -c string with quotes inside a launchd plist is XML
# that has to be escaped by hand, and the version that is not escaped is the one
# that silently fails to load. A file has no such rule.
#
# It loops because the contract does: `outbox flush` exits 0 when the queue is
# empty and 2 while items remain, so "keep going while there is work" needs no
# state and no daemon. sleep 20 because a retry storm against a peer whose
# descriptor is still publishing (measured: ~182s) spends circuits for nothing.
OUTBOX_SH="$HOME_DIR/outbox-flush.sh"
cat > "$OUTBOX_SH" <<FLUSHER
#!/bin/sh
# Generated by setup.sh. Drains \$HOME_DIR/state/outbox until it is empty.
while "$VPY" "$HOME_DIR/inbox_agent.py" outbox flush; do
  sleep 20
done
exit 0
FLUSHER
chmod +x "$OUTBOX_SH"

if [ "$OS" = mac ]; then
  LA="$HOME_DIR/launchagents"; mkdir -p "$LA"

  write_plist() { # label, outfile, then program args one per line after --
    local label="$1" out="$2"; shift 2
    {
      printf '<?xml version="1.0" encoding="UTF-8"?>\n'
      printf '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" '
      printf '"http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
      printf '<plist version="1.0"><dict>\n'
      printf '  <key>Label</key><string>%s</string>\n' "$label"
      printf '  <key>ProgramArguments</key><array>\n'
      for a in "$@"; do printf '    <string>%s</string>\n' "$a"; done
      printf '  </array>\n'
      printf '  <key>RunAtLoad</key><true/>\n'
      printf '  <key>KeepAlive</key><true/>\n'
      printf '  <key>WorkingDirectory</key><string>%s</string>\n' "$HOME_DIR"
      printf '  <key>EnvironmentVariables</key><dict>\n'
      printf '    <key>TORAGENTS_HOME</key><string>%s</string>\n' "$HOME_DIR"
      printf '    <key>TORAGENTS_PORT</key><string>%s</string>\n' "$PORT"
      printf '    <key>TORAGENTS_SOCKS</key><string>%s</string>\n' "$SOCKS"
      printf '    <key>PATH</key><string>/usr/bin:/bin:/usr/sbin:/sbin:/opt/homebrew/bin:/usr/local/bin</string>\n'
      printf '  </dict>\n'
      printf '  <key>StandardOutPath</key><string>%s/%s.out.log</string>\n' "$HOME_DIR" "$label"
      printf '  <key>StandardErrorPath</key><string>%s/%s.err.log</string>\n' "$HOME_DIR" "$label"
      printf '</dict></plist>\n'
    } > "$out"
  }

  write_plist com.toragents.tor  "$LA/com.toragents.tor.plist"  "$TORBIN" -f "$HOME_DIR/torrc"
  write_plist com.toragents.inbox "$LA/com.toragents.inbox.plist" "$VPY" "$HOME_DIR/inbox_agent.py" serve
  # The flusher. Without a process to drain state/outbox/, "queue first, send
  # second" only moves the loss one file to the left: a letter that failed to dial
  # would sit in the queue until a human ran `outbox flush` by hand -- which is the
  # behaviour that lost two letters for an hour on 2026-10-20. The loop exits 0 the
  # moment the queue is empty and 2 while items remain, so this stays a loop and
  # not a daemon that has to know when it is done.
  write_plist com.toragents.outbox "$LA/com.toragents.outbox.plist" /bin/sh "$OUTBOX_SH"
  ok "plists written to $LA"

  if [ "$DRY" = 0 ] && [ "$NOSVC" = 0 ]; then
    REAL_LA="$HOME/Library/LaunchAgents"; mkdir -p "$REAL_LA"
    cp "$LA"/*.plist "$REAL_LA"/
    for p in "$REAL_LA"/com.toragents.*.plist; do
      launchctl bootout "gui/$UID" "$p" 2>/dev/null || launchctl unload "$p" 2>/dev/null || true
      launchctl bootstrap "gui/$UID" "$p" 2>/dev/null || launchctl load "$p"
    done
    ok "services bootstrapped"
  fi
else
  UD="$HOME_DIR/systemd"; mkdir -p "$UD"
  cat > "$UD/toragents-tor.service" <<UNIT
[Unit]
Description=tor for toragents (hidden service)

[Service]
ExecStart=$TORBIN -f $HOME_DIR/torrc
Restart=always
RestartSec=5

[Install]
WantedBy=default.target
UNIT
  cat > "$UD/toragents-inbox.service" <<UNIT
[Unit]
Description=toragents inbox daemon
After=toragents-tor.service

[Service]
ExecStart=$VPY $HOME_DIR/inbox_agent.py serve
Environment=TORAGENTS_HOME=$HOME_DIR
Environment=TORAGENTS_PORT=$PORT
Environment=TORAGENTS_SOCKS=$SOCKS
Restart=always
RestartSec=5

[Install]
WantedBy=default.target
UNIT
  cat > "$UD/toragents-outbox.service" <<UNIT
[Unit]
Description=toragents outbox flusher (drains letters that failed to dial)
After=toragents-tor.service

[Service]
ExecStart=/bin/sh $OUTBOX_SH
Environment=TORAGENTS_HOME=$HOME_DIR
Environment=TORAGENTS_SOCKS=$SOCKS
Restart=always
RestartSec=10

[Install]
WantedBy=default.target
UNIT
  ok "units written to $UD"
  if [ "$DRY" = 0 ] && [ "$NOSVC" = 0 ]; then
    RD="$HOME/.config/systemd/user"; mkdir -p "$RD"; cp "$UD"/*.service "$RD"/
    systemctl --user daemon-reload
    systemctl --user enable --now toragents-tor.service toragents-inbox.service toragents-outbox.service 2>/dev/null || true
    # No user systemd session (containers, WSL, some minimal installs): the units
    # exist but nothing will ever start them, and the install would sit waiting
    # for a hostname that never appears. Start them directly instead and say so.
    sleep 2
    # The unit NAME is global, so "is it active?" is not our question. A second
    # install on the same machine, or an older one, answers yes for ITS unit
    # while watching a different directory -- and then this install waits for a
    # hostname in a folder nobody is writing to.
    TOR_UNIT_HOME="$(systemctl --user show -p ExecStart --value toragents-tor.service 2>/dev/null || true)"
    case "$TOR_UNIT_HOME" in
      *"$HOME_DIR"*) ;;
      *) TOR_UNIT_HOME="" ;;
    esac
    if [ -n "$TOR_UNIT_HOME" ] && systemctl --user is-active --quiet toragents-tor.service 2>/dev/null; then
      # Tor is already serving THIS install. A restart would unpublish the onion
      # for ~3 minutes (182 s measured) while everything else looks fine, so an
      # update must never touch it: rewriting payload files does not need a new
      # tor, and the daemon restarts in well under a second.
      ok "tor already serving this install -- left running (onion stays published)"
      systemctl --user restart toragents-inbox.service 2>/dev/null || true
      TOR_WAS_RUNNING=1
      AUTOSTARTED=1
    elif [ -z "$TOR_UNIT_HOME" ] || ! systemctl --user is-active --quiet toragents-tor.service 2>/dev/null; then
      warn "no user systemd session -- starting tor and the daemon directly"
      # A tor already running on THIS torrc is the same onion; starting a second
      # one would fail to lock DataDirectory, and killing the old one would cost
      # the 3-minute republish. Leave it alone.
      RUNNING_TOR=""
      for p in $(ss -ltnp 2>/dev/null | grep -o 'pid=[0-9]*' | cut -d= -f2 | sort -u); do
        case "$(tr '\0' ' ' < "/proc/$p/cmdline" 2>/dev/null)" in
          *"-f $HOME_DIR/torrc"*) RUNNING_TOR="$p"; break ;;
        esac
      done
      if [ -n "$RUNNING_TOR" ]; then
        ok "tor pid $RUNNING_TOR already serving $HOME_DIR/torrc -- left running"
        TOR_WAS_RUNNING=1
      else
      nohup "$TORBIN" -f "$HOME_DIR/torrc" > "$HOME_DIR/tor.log" 2>&1 &
      sleep 2
      fi
      nohup env TORAGENTS_HOME="$HOME_DIR" TORAGENTS_PORT="$PORT" TORAGENTS_SOCKS="$SOCKS" \
        "$VPY" "$HOME_DIR/inbox_agent.py" serve > "$HOME_DIR/inbox.log" 2>&1 &
      AUTOSTARTED=0
    else
      ok "services enabled"
      AUTOSTARTED=1
    fi
  fi
fi

# ------------------------------------------------------------------ peer ---
if [ -n "$PEER_FP" ] || [ -n "$PEER_ONION" ]; then
  [ -n "$PEER_FP" ] && [ -n "$PEER_ONION" ] \
    || die "give both --peer-fp and --peer-onion, or neither"
  if [ "$DRY" = 1 ]; then
    warn "dry-run: would allowlist $PEER_LABEL ($PEER_FP)"
  else
    printf '{\n  "%s": {"onion": "%s", "label": "%s", "added": %s}\n}\n' \
      "$PEER_FP" "$PEER_ONION" "$PEER_LABEL" "$(date +%s)" > "$HOME_DIR/state/peers.json"
    chmod 600 "$HOME_DIR/state/peers.json"
    ok "peer allowlisted: $PEER_LABEL"
  fi
else
  warn "no peer given -- nobody can send yet"
fi

# ------------------------------------------------------- first bootstrap ---
if [ "$DRY" = 1 ]; then
  say "dry-run complete. Nothing was started."
  printf '  torrc        %s/torrc\n  plists/units %s\n' "$HOME_DIR" "$HOME_DIR"
  exit 0
fi

# With --no-service tor is never started, so the hostname file never appears.
# Waiting here was a hang: the install finished and then blocked forever.
if [ "$NOSVC" = 1 ]; then
  say "Supervisors skipped (--no-service)"
  printf '  Start tor, then your onion appears in %s/hs/hostname\n\n' "$HOME_DIR"
  printf '    %s -f %s/torrc &\n' "$TORBIN" "$HOME_DIR"
  printf '    TORAGENTS_HOME=%s %s %s/inbox_agent.py serve &\n\n' "$HOME_DIR" "$VPY" "$HOME_DIR"
  printf '  Your fingerprint:\n'
  printf '    TORAGENTS_HOME=%s %s %s/inbox_agent.py whoami\n\n' "$HOME_DIR" "$VPY" "$HOME_DIR"
  printf '  Re-running this installer later is safe; it never rotates the identity.\n'
  exit 0
fi

if [ "${AUTOSTARTED:-1}" = 0 ]; then
  warn "these processes will NOT restart on reboot: this machine has no user systemd"
fi

say "Waiting for tor to publish the hidden service"
printf '  (first run bootstraps the tor network -- up to 3 minutes, be patient)\n'
i=0
while [ ! -s "$HOME_DIR/hs/hostname" ]; do
  i=$((i+1))
  if [ $i -gt 200 ]; then
    printf '\n'
    die "timed out waiting for $HOME_DIR/hs/hostname
  Check $HOME_DIR/tor.log -- it should reach 'Bootstrapped 100%'.
  Most common cause on macOS: a homebrew tor already holds port $SOCKS.
  Re-run with TORAGENTS_SOCKS=9062"
  fi
  sleep 1
done
ONION="$(cat "$HOME_DIR/hs/hostname")"

# The hostname file proves a KEY EXISTS, not that the network can reach us: it is
# written before tor uploads a descriptor, and a restarted tor takes ~3 minutes
# (182 s measured) to be reachable again. Saying INSTALLED on the strength of the
# file is how a machine ends up looking installed while every dial to it fails.
if [ "$DRY" = 0 ] && command -v curl >/dev/null 2>&1; then
  i=0; CODE=000
  while [ "$i" -lt 90 ]; do
    # curl writes 000 to stdout when it fails, so "|| echo 000" produced 000000
    # and a `!= 000` test read that as success. Exit status decides, not output.
    CODE="$(curl -s -o /dev/null -m 8 -w '%{http_code}' --socks5-hostname 127.0.0.1:"$SOCKS" "http://$(cat "$HOME_DIR/hs/hostname")/" 2>/dev/null)" || CODE=000
    case "$CODE" in 2*|3*|4*) break ;; esac
    CODE=000
    i=$((i+3)); sleep 3
  done
  if [ "$CODE" != "000" ]; then
    ok "onion answers on its own socks port (http $CODE after ${i}s)"
  elif [ "${TOR_WAS_RUNNING:-0}" = 1 ]; then
    warn "tor was already running but the onion did not answer in ${i}s"
    warn "this is not a fresh-publish wait: check $HOME_DIR/tor.log, do NOT reinstall"
  else
    warn "onion not yet reachable after ${i}s (normal on a first publish: up to 3 min)"
    warn "it will come up on its own; reinstalling restarts the clock, so wait"
  fi
fi
# init explicitly: whoami is read-only now and must never mint an identity
TORAGENTS_HOME="$HOME_DIR" "$VPY" "$HOME_DIR/inbox_agent.py" init >/dev/null
FP="$(TORAGENTS_HOME="$HOME_DIR" "$VPY" "$HOME_DIR/inbox_agent.py" whoami | awk '/fingerprint/{print $2}')"

cat <<DONE

============================================================================
  INSTALLED. Send these two values back:

  onion        $ONION
  fingerprint  $FP

  The onion is this machine's permanent address. The fingerprint is its ID.
  Your peer must allowlist the fingerprint before they can be reached.
============================================================================

  logs    $HOME_DIR/*.log
  state   $HOME_DIR/state
  stop    $( [ "$OS" = mac ] && echo "launchctl bootout gui/\$UID ~/Library/LaunchAgents/com.toragents.*.plist" || echo "systemctl --user stop toragents-tor toragents-inbox toragents-outbox" )
  start   $( [ "$OS" = mac ] && echo "launchctl bootstrap gui/\$UID ~/Library/LaunchAgents/com.toragents.inbox.plist" || echo "systemctl --user start toragents-inbox" )

  Inside your agent:
    export TORAGENTS_HOME=$HOME_DIR
    $VPY \$TORAGENTS_HOME/inbox_agent.py inbox
    $VPY \$TORAGENTS_HOME/inbox_agent.py send --to $PEER_LABEL --body "hi"
DONE
